 const expected=ownedFixture(),initial=new AbortController();initial.abort();await expect(vdi3805SnapshotToSqliteDatabase(expected,{signal:initial.signal})).rejects.toHaveProperty("kind","canceled");const database=await vdi3805SnapshotToSqliteDatabase(expected);await expect(vdi3805SnapshotFromSqliteDatabase(database,{signal:initial.signal})).rejects.toHaveProperty("kind","canceled");expected.catalog.products[0]!.records[0]!.fields=Array.from({length:controls.entityCount},()=>"任意\u0000field");const large=await vdi3805SnapshotToSqliteDatabase(expected);for(const phase of["projectSnapshot","reconstructSnapshot"] as const){const c=new AbortController();let reached=false;const options={signal:c.signal,onProgress:(event:{phase:string;completed:number})=>{if(event.phase===phase&&event.completed>=controls.cancelAt){reached=true;c.abort()}}};await expect(phase==="projectSnapshot"?vdi3805SnapshotToSqliteDatabase(expected,options):vdi3805SnapshotFromSqliteDatabase(large,options)).rejects.toHaveProperty("kind","canceled");expect(reached).toBe(true)}expected.catalog.file.manufacturer="x".repeat(controls.largeTextBytes);await expect(vdi3805SnapshotToSqliteDatabase(expected,{maxValueBytes:controls.largeTextBytes-1})).rejects.toThrow();await expect(vdi3805SnapshotToSqliteDatabase(expected,{maxRows:1})).rejects.toThrow();
